WITH by_dimension AS (SELECT dim.channel, a.status AS payment_status, COUNT(*) AS num_rows, AVG(a.amount) AS avg_amount FROM payments a LEFT JOIN orders dim ON a.order_id = dim.id GROUP BY dim.channel, a.status) SELECT channel, payment_status, CASE WHEN channel RLIKE '^(mobile|web)$' THEN 'PRIORITY' WHEN channel RLIKE '^(store|partner)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS channel_zone FROM by_dimension;
